contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "zero deposit would revert in LogFile? actually it just logs");
        require(address(this).balance >= amount, "need ether to deposit");

        uint senderBalBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint senderBalAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(
            senderBalAfter == senderBalBefore + amount &&
            cBalAfter == cBalBefore + amount
        );
    }

    receive() external payable {}
}

