// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 senderBalBefore;
        try c.balances(address(this)) returns (uint256 __r) { senderBalBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 senderBalAfter;
        try c.balances(address(this)) returns (uint256 __r) { senderBalAfter = __r; } catch { return; }
        uint cBalAfter = address(c).balance;
        assertTrue(senderBalAfter == senderBalBefore + amount &&
            cBalAfter == cBalBefore + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
